/// Contract's constructor arguments.
#[allow(dead_code, unused_imports, unused_variables)]
pub mod constructor {
    const INTERNAL_ERR: &str = "`ethabi_derive` internal error";
    #[derive(Debug, Clone, PartialEq)]
    pub struct Constructor {
        pub name: String,
        pub symbol: String,
        pub default_operators: Vec<Vec<u8>>,
    }
    impl Constructor {
        pub fn decode(data: &[u8]) -> Result<Self, String> {
            let mut values = ethabi::decode(
                    &[
                        ethabi::ParamType::String,
                        ethabi::ParamType::String,
                        ethabi::ParamType::Array(Box::new(ethabi::ParamType::Address)),
                    ],
                    data.as_ref(),
                )
                .map_err(|e| format!("unable to decode constructor input: {:?}", e))?;
            values.reverse();
            Ok(Self {
                name: values
                    .pop()
                    .expect(INTERNAL_ERR)
                    .into_string()
                    .expect(INTERNAL_ERR),
                symbol: values
                    .pop()
                    .expect(INTERNAL_ERR)
                    .into_string()
                    .expect(INTERNAL_ERR),
                default_operators: values
                    .pop()
                    .expect(INTERNAL_ERR)
                    .into_array()
                    .expect(INTERNAL_ERR)
                    .into_iter()
                    .map(|inner| {
                        inner.into_address().expect(INTERNAL_ERR).as_bytes().to_vec()
                    })
                    .collect(),
            })
        }
        pub fn encode(&self) -> Vec<u8> {
            ethabi::encode(
                &[
                    ethabi::Token::String(self.name.clone()),
                    ethabi::Token::String(self.symbol.clone()),
                    {
                        let v = self
                            .default_operators
                            .iter()
                            .map(|inner| ethabi::Token::Address(
                                ethabi::Address::from_slice(&inner),
                            ))
                            .collect();
                        ethabi::Token::Array(v)
                    },
                ],
            )
        }
    }
}
